_SHELL = """<!doctype html>
<html{theme_attr}>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{title}</title>
<link rel="icon" href="/favicon.ico" sizes="32x32">
<link rel="icon" type="image/svg+xml" href="/venona-mark.svg">
<link rel="apple-touch-icon" href="/apple-touch-icon.png">
<link rel="manifest" href="/manifest.json">
<link rel="stylesheet" href="{public_css}">
<style>
  /* The whole theme switch, and the same two rules `web/src/styles/tokens.css`
     carries: they declare `color-scheme` and nothing else, so every
     `light-dark()` in the sheet above follows without a second palette to keep
     in step. No attribute is System, which is why the bare `:root` says
     `light dark`.

     INLINE rather than in the generated sheet, because these three are pinned
     verbatim by `tests/test_theme_boot.py` -- the attribute is what the server
     writes, and the rules that read it have to be where that is decided. */
  :root {{ color-scheme: light dark; }}
  :root[data-theme='light'] {{ color-scheme: light; }}
  :root[data-theme='dark'] {{ color-scheme: dark; }}
{field_css}
</style>
</head>
<body>
{field}{field_script}
<main{main_class}>
{lockup}
{body}
</main>
</body>
</html>"""


#: The reader's choice, shared across every Venona property by a cookie scoped
#: to the registrable domain. Spelled the same in `web/src/stores/theme.ts`, every
#: `theme-boot.js` copy and `api/routers/oauth.py`, none of which can import it
#: from another; `tests/test_theme_boot.py` holds them equal. docs/adr/0177.
THEME_COOKIE = "venona.theme"


def theme_of(request: Request) -> str | None:
    """Which palette to pin, from the shared cookie.

    Only the two explicit choices pin anything. `system` and an unrecognised
    value both render NO attribute, because the absence of `data-theme` is what
    makes the page follow the operating system -- there is no third rule to
    write, and a value a reader can edit in a console should degrade to the
    default rather than reach the template.

    Server-side because the theme has to be right in the first painted frame
    and these pages must not need a script to get there. The public half of the
    hub -- sign-in, the chooser, request-access, the refusals -- carries no
    bundle by design (epic D: auth pages must not depend on one), so a boot
    script is not available to it the way it is to the app and to the operator
    surface. The reward is that this half works with scripts off, which neither
    of those does.
    """
    choice = request.cookies.get(THEME_COOKIE)
    return choice if choice in ("light", "dark") else None


def _main_class(*, wide: bool, bare: bool) -> str:
    names = [name for name, on in (("wide", wide), ("bare", bare)) if on]
    return f' class="{" ".join(names)}"' if names else ""


def _page(
    title: str,
    body: str,
    *,
    wide: bool = False,
    bare: bool = False,
    theme: str | None = None,
    field: bool = False,
) -> str:
    """The shell. `field` puts the graph behind the panel.

    On every public page, because a visitor arriving from example.com -- where
    the field IS the page -- reads a bare panel on a flat ground as a different
    company. Off the operator surface, where it would compete with a table of
    addresses. ADR 0191; `tests/hub/test_hub_errors.py` holds both halves.
    """
    return _SHELL.format(
        title=html.escape(title),
        public_css=PUBLIC_CSS_URL,
        lockup=_LOCKUP,
        body=body,
        main_class=_main_class(wide=wide, bare=bare),
        theme_attr=f' data-theme="{theme}"' if theme in ("light", "dark") else "",
        field=FIELD if field else "",
        field_css=FIELD_CSS if field else "",
        # `defer` so it never blocks the parse, and after the field markup so
        # there is nothing to wait for. Only on pages that HAVE a field: a
        # script tag on a page with nothing to draw on is a request that can
        # only fail to do anything. The URL names the bundle's own bytes, which
        # is what lets `routers/brand.py` answer it as immutable.
        field_script=(f'\n<script src="{SCRIPT_URL}" defer></script>' if field else ""),
    )


def sign_in(*, next_path: str, on_sale: bool = False, theme: str | None = None) -> str:
    """`on_sale` is whether any domain could be bought on the spot.

    It removes the offer to ask a person, because on a hub that sells there is
    nothing for a person to decide: `/request-access` bounces a stranger who
    can buy straight back to the chooser, so the link is a round trip to where
    they already were. The same reason the chooser drops its own standing
    invitation once every card is theirs or buyable.
    """
    href = "/auth/google?next=" + html.escape(next_path, quote=True)
    footer = (
        ""
        if on_sale
        else '<p class="footer">No account? <a href="/request-access">Request access</a>.</p>'
    )
    return _page(
        "Venona",
        "<h1>Sign in</h1>"
        f'<div class="actions"><a class="gbtn" href="{href}">{_GOOGLE_G}Sign in with Google</a></div>'
        + footer,
        theme=theme,
        field=True,
    )


def _stale_since(last_seen: Any, *, now: float) -> str:
    """The date a domain last answered, but ONLY when that is old enough to
    matter. Empty for a domain that answered within the hour, so a card in the
    ordinary case carries no caveat at all.

    `now` is passed in rather than read: this module renders, and a renderer
    that asks what time it is cannot be tested against a fixed clock.
    """
    if last_seen is None:
        return ""
    stamp = last_seen if hasattr(last_seen, "timestamp") else None
    if stamp is None:
        return ""
    if now - stamp.timestamp() < STALE_STATUS_SECONDS:
        return ""
    return html.escape(str(last_seen)[:10])


#: Enough to name every discount a sane annual price produces. Words rather
#: than digits because this is a phrase in a sentence, not a figure to compare.
_MONTH_WORDS = {1: "one", 2: "two", 3: "three", 4: "four", 5: "five", 6: "six"}


def _annual_saving(monthly: int | None, annual: int | None) -> str:
    """What the yearly plan saves, said the way the pricing page says it.

    COMPUTED, never written down. Marketing's "Two months free" is prose beside
    a hardcoded figure; this is the same claim made from the prices the domain
    is actually charging, so a repriced domain cannot end up advertising a
    discount it stopped giving.

    Silent unless the answer is a whole number of months within a cent. A yearly
    price that is not a clean multiple has no short honest phrase, and "1.87
    months free" is worse than the price standing on its own.
    """
    if not monthly or not annual or annual >= monthly * 12:
        return ""
    free_months = (monthly * 12 - annual) / monthly
    nearest = round(free_months)
    if abs(free_months - nearest) * monthly > 1 or nearest not in _MONTH_WORDS:
        return ""
    return f"{_MONTH_WORDS[nearest]} months free" if nearest > 1 else "one month free"


def _money(amount: int | None, currency: str | None) -> str:
    """A price a person reads, from Stripe's minor units.

    `$12`, not `$12.00`: a whole amount with trailing zeros reads as a form
    field rather than a price. Currencies this does not know render as
    `39 CHF` -- wrong-looking is better than confidently wrong, and the
    symbol table stays one line long until there is a second currency.
    """
    if amount is None or not currency:
        return ""
    minor = 0 if currency.lower() in ZERO_DECIMAL else 2
    value = amount if minor == 0 else amount / 100
    symbol = {"usd": "$", "gbp": "\u00a3", "eur": "\u20ac"}.get(currency.lower())
    body = f"{value:,.0f}" if value == int(value) else f"{value:,.2f}"
    return f"{symbol}{body}" if symbol else f"{body} {currency.upper()}"


#: Currencies with no minor unit. Stripe quotes these in whole units, so
#: dividing by 100 would price a domain at a hundredth of what it costs.
ZERO_DECIMAL = frozenset({"jpy", "krw", "vnd", "clp", "isk"})


#: How old a status poll may be before the figures beside it need a caveat.
#:
#: The poller runs every five minutes and demotes an instance to `offline` after
#: three misses, so anything past an hour means the polling itself has stopped
#: -- a hub with `HUB_POLL_ENABLED=0`, or a poller that died. The status column
#: says `live` throughout that, because nothing has demoted it, which is exactly
#: how a card ends up asserting a month-old corpus size as current fact.
STALE_STATUS_SECONDS = 3600


def domains(
    *,
    email: str,
    rows: list[dict[str, Any]],
    self_serve: bool,
    billing_enabled: bool,
    trial_days: int,
    now: float,
    display_name: str | None = None,
    operator: bool = False,
    theme: str | None = None,
) -> str:
    """The hub's front door: what this reader holds, and what they could add.

    ONE PAGE FOR BOTH, because they are one question asked about different
    rows. A list of memberships on its own can only say "you have these", and
    the reader wanting another has to be sent somewhere else to get it -- which
    for a priced domain meant a form asking a person to decide.

    A GALLERY RATHER THAN A DROPDOWN, because this is a page somebody CHOOSES
    on. A list of names in a `<select>` says nothing about what any domain
    covers, what it costs, or that the trial costs nothing -- which with one
    domain is merely thin, and with two is a choice nobody can make.

    Every field here is one the domain already publishes about itself: its
    `login_blurb` is the sentence it shows on its own login page, and the
    figures ride the status envelope the hub already polls for. A description
    written HERE, about somebody else's corpus, is one that drifts.

    The button says what will actually happen, which differs by domain and by
    what the hub is configured to do. A card that offered a trial an unpriced
    domain cannot start would be a 409 with a friendly label on it.
    """
    cards = []
    # Whether anything on this page is a dead end for this reader: a domain they
    # cannot open and cannot buy. It decides whether the footer offers to ask a
    # person, below.
    any_dead_end = False
    for row in rows:
        status = row["last_status"] if isinstance(row.get("last_status"), dict) else {}
        blurb = str(status.get("login_blurb") or row.get("tagline") or "")
        monthly = _money(row.get("price_monthly_amount"), row.get("price_currency"))
        annual = _money(row.get("price_annual_amount"), row.get("price_currency"))
        sellable = not billing_state.blockers(
            self_serve=self_serve,
            takes_payment=billing_enabled,
            price_id=row.get("stripe_price_monthly"),
        )
        any_dead_end = any_dead_end or not (row.get("role") or sellable)

        # WHAT WAS UNDERSTOOD, not what was fetched. A document count measures
        # how much a domain read; the graph is what it made of it, and a domain
        # that pulled four hundred articles and drew nothing out of them would
        # otherwise look identical to one that built something from them.
        #
        # `names` and `relationships` because that is what a reader calls them.
        # `entities` and `assertions` are this repo's words for its own tables.
        facts = []
        if status.get("entities"):
            facts.append(f"{int(status['entities']):,} names")
        if status.get("relationships"):
            facts.append(f"{int(status['relationships']):,} relationships")
        if status.get("latest_brief_at"):
            facts.append(f"last brief {html.escape(str(status['latest_brief_at'])[:10])}")
        # EVERY FIGURE ABOVE IS SECOND-HAND, and none of it is ours. They come
        # from the last status poll, so the card is quoting what that domain
        # said whenever it last spoke -- and `live` is not a claim about when
        # that was. Saying so is the difference between a figure and a promise.
        stale = _stale_since(row.get("last_seen_at"), now=now)
        if row["status"] == "offline":
            facts.append(f"not answering since {stale}" if stale else "not answering right now")
        elif stale and facts:
            facts.append(f"as it stood on {stale}")

        if row.get("role"):
            action = (
                '<a class="button" href="{url}">Open</a>'.format(
                    url=html.escape(
                        row["public_url"].rstrip("/") + "/api/auth/login?next=/", quote=True
                    )
                )
                + f'<span class="badge">{html.escape(row["role"])}</span>'
            )
            terms = ""
        elif sellable:
            # ONE BUTTON PER PLAN, both carrying their price. A reader choosing
            # between two plans is choosing between two numbers, so both numbers
            # are on the controls that charge them.
            #
            # `form.buy` is the filled treatment and `form.inline` the outline
            # one Sign out wears, so the year leads and the month reads as the
            # alternative rather than an afterthought. Both are forms, never a
            # link: a GET that creates a Checkout Session is reachable by a link
            # prefetcher, and this is the button that takes money.
            slug = html.escape(row["slug"], quote=True)
            # A domain priced monthly and not yearly is a real state
            # (`set_pricing` writes both, but `sellable` turns only on the
            # monthly id), and one button is the honest rendering of it.
            both_plans = bool(row.get("stripe_price_annual") and annual)
            saving = (
                _annual_saving(row.get("price_monthly_amount"), row.get("price_annual_amount"))
                if both_plans
                else ""
            )
            # AN ASTERISK ON THE PRICE IT BELONGS TO. The note lands beside the
            # buttons on a wide card and under them on a phone, so its position
            # cannot be what says which plan it discounts. A marker says that at
            # every width.
            star = "*" if saving else ""
            buttons = []
            if both_plans:
                # THE NOTE IS INSIDE THE YEAR'S OWN COLUMN, so containment says
                # which price it discounts and no reading of the row can move it
                # onto the month. The star repeats that in text, for a reader
                # skimming the buttons alone.
                year = (
                    f'<form class="buy" method="post" action="/domains/{slug}/start?plan=annual">'
                    f"<button>{html.escape(annual)} a year{star}</button></form>"
                )
                if saving:
                    year = (
                        f'<div class="plan">{year}'
                        f'<span class="badge">* {html.escape(saving)}</span></div>'
                    )
                buttons.append(year)
            buttons.append(
                f'<form class="{"inline" if both_plans else "buy"}" method="post" '
                f'action="/domains/{slug}/start?plan=monthly">'
                f"<button>{html.escape(monthly)} a month</button></form>"
            )
            action = "".join(buttons)
            # NAMES NO SINGLE AMOUNT. Two prices are on offer, so a sentence
            # naming one of them describes the wrong plan half the time. Both
            # are on the buttons this sits directly under.
            terms = (
                f'<p class="terms">{trial_days} days free'
                f"{' on either plan' if both_plans else ''}. We take a card now, and "
                f"{'the one you pick' if both_plans else 'it'} starts on day {trial_days} "
                "unless you cancel. You can cancel any time.</p>"
            )
        else:
            action = (
                '<a class="button" href="/request-access?instance={slug}">Request access</a>'
            ).format(slug=html.escape(row["slug"], quote=True))
            terms = ""

        # NOT WHERE THE BUTTONS CARRY IT. A card on sale names both prices on
        # the controls that charge them, and a third figure in the corner is the
        # same number twice with nothing to say which one you get.
        price = ""
        if monthly and annual and not sellable:
            price = f'<span class="badge">{html.escape(monthly)} a month</span>'

        cards.append(
            '<li><div class="card-head"><span class="name">{name}</span>{price}</div>'
            "{tagline}{blurb}{facts}"
            '<div class="card-actions">{action}</div>{terms}</li>'.format(
                name=html.escape(row["display_name"]),
                price=price,
                # The tagline is a SUBTITLE, so it sits tight under the name it
                # belongs to. Dropped entirely when the blurb repeats it, which
                # is what happens on a domain that has not written one.
                tagline=(
                    f'<p class="card-sub">{html.escape(row["tagline"])}</p>'
                    if row["tagline"] and row["tagline"] != blurb
                    else ""
                ),
                blurb=f'<p class="card-blurb">{html.escape(blurb)}</p>' if blurb else "",
                facts=(
                    '<p class="card-facts">' + html.escape(" \u00b7 ".join(facts)) + "</p>"
                    if facts
                    else ""
                ),
                action=action,
                terms=terms,
            )
        )

    if not cards:
        # No public domain at all: a fresh hub, or every one of them retired.
        # An empty list with no words reads as a page that failed to load.
        return _page(
            "Venona",
            f"<h1>Domains</h1><p>Signed in as {html.escape(email)}.</p>"
            "<p>There is nothing to read here yet. Venona has no domain open to "
            "new readers at the moment.</p>"
            '<div class="footer footer--row"><a href="/request-access">Ask anyway</a>'
            '<form class="inline" method="post" action="/logout">'
            "<button>Sign out</button></form></div>",
            theme=theme,
            field=True,
        )

    # THE HEADING FOLLOWS WHAT IS IN THE LIST. `Your domains` over a list of
    # things somebody does not have is wrong, and `Domains` over the one they
    # read every morning is colder than it needs to be.
    mine = any(row.get("role") for row in rows)
    if mine:
        intro = (
            "<p>Yours first, then the rest of what Venona reads.</p>"
            if len(rows) > sum(1 for row in rows if row.get("role"))
            else "<p>Pick up where you left off.</p>"
        )
    elif self_serve:
        intro = "<p>Pick the one you want to read. You can add another later.</p>"
    else:
        intro = "<p>Ask for the one you want to read. Somebody approves it by hand.</p>"
    who = html.escape(display_name or email)
    return _page(
        "Venona",
        f"<h1>{'Your domains' if mine else 'Domains'}</h1><p>Signed in as {who}.</p>"
        + intro
        + f'<ul class="instances cards">{"".join(cards)}</ul>'
        + _catalog_footer(any_dead_end=any_dead_end, operator=operator),
        theme=theme,
        field=True,
    )


def _catalog_footer(*, any_dead_end: bool, operator: bool) -> str:
    """Sign out, and whatever else this reader has business with.

    ASKING A PERSON APPEARS ONLY WHERE THERE IS SOMETHING TO ASK ABOUT. With
    every domain either already theirs or buyable on the spot, an invitation to
    ask is an offer of a slower way to do what the button above just did. It
    stays wherever a card is a dead end, because a reader who can neither open
    nor buy the only domain on offer would otherwise have no path forward at
    all (`test_memberless_flow_has_a_path_forward`).
    """
    links = []
    if operator:
        links.append('<a href="/admin">Admin</a>')
    if any_dead_end:
        links.append('<a href="/request-access">Ask for something else</a>')
    left = f"<span>{' &middot; '.join(links)}</span>" if links else ""
    row = "footer footer--row" if links else "footer footer--row footer--end"
    return (
        f'<div class="{row}">{left}'
        '<form class="inline" method="post" action="/logout"><button>Sign out</button></form>'
        "</div>"
    )


def request_access_form(
    *,
    email: str | None,
    instances: list[dict[str, Any]],
    signed_in: bool,
    self_serve: bool = False,
    wanted: str | None = None,
    theme: str | None = None,
) -> str:
    """The queue. Still here for somebody who wants a domain that is not on
    offer, and for a separate front page, which posts to the same endpoint.

    `self_serve` CHANGES THE WORDS AND NOTHING ELSE. With the door open this
    submission grants rather than queues, so telling a signed-in visitor to ask
    a person and labelling the button "Send request" describes something that
    will not happen. The route decides; this only stops the page lying about it.
    """
    options = '<option value="">Any / not sure</option>' + "".join(
        '<option value="{slug}"{sel}>{name}</option>'.format(
            slug=html.escape(row["slug"], quote=True),
            name=html.escape(row["display_name"]),
            sel=" selected" if row["slug"] == wanted else "",
        )
        for row in instances
    )
    email_value = html.escape(email or "", quote=True)
    if signed_in and self_serve:
        intro = "<p>Pick a domain and it is yours. You can add another later.</p>"
    elif signed_in:
        intro = "<p>You have nothing here yet. Ask the person who runs Venona for access.</p>"
    else:
        intro = "<p>Tell the person who runs Venona who you are and what you need.</p>"
    cta = "Start reading" if signed_in and self_serve else "Send request"
    footer = (
        '<div class="footer footer--row"><a href="/">Back</a>'
        '<form class="inline" method="post" action="/logout"><button>Sign out</button></form>'
        "</div>"
        if signed_in
        else '<p class="footer"><a href="/">Back</a></p>'
    )
    return _page(
        "Request access",
        "<h1>Request access</h1>" + intro + '<form class="stack" method="post" '
        'action="/request-access">'
        f'<label>Email</label><input name="email" type="email" required maxlength="254" '
        f'value="{email_value}">'
        f'<label>Domain</label><select name="instance">{options}</select>'
        '<label>Note</label><textarea name="note" rows="3" maxlength="2000"></textarea>'
        f'<div class="actions"><button>{cta}</button></div>'
        "</form>" + footer,
        theme=theme,
        field=True,
    )


def request_pending(*, email: str, theme: str | None = None) -> str:
    """The signed-in memberless portal once a request for the session's email
    is pending: standing status instead of the form again, and the two ways
    onward. "Check again" reloads `/`, which re-reads memberships per request
    -- the moment a grant lands, that click is the chooser."""
    who = html.escape(email)
    return _page(
        "Request pending",
        "<h1>Request pending</h1>"
        f"<p>Signed in as {who}.</p>"
        "<p>Your access request is with the person who runs Venona. Once access "
        "is granted, your domains appear here.</p>"
        '<div class="actions"><a class="button" href="/">Check again</a></div>'
        '<div class="footer footer--row">'
        '<a href="/request-access">Request access to another domain</a>'
        '<form class="inline" method="post" action="/logout"><button>Sign out</button></form>'
        "</div>",
        theme=theme,
        field=True,
    )


def request_access_done(*, theme: str | None = None) -> str:
    """One page, returned for EVERY submission outcome -- first, duplicate,
    known account, unknown instance. It varies with the reader's own theme
    cookie and with NOTHING else: any variation that tracks the submission is
    an account-existence oracle (ADR 0141), and the theme is a property of the
    browser asking, not of the address it asked about.
    `test_request_access_is_byte_identical_for_every_outcome` pins the first."""
    return _page(
        "Request received",
        "<h1>Request received</h1>"
        "<p>If access is granted, signing in with Google will take you to your "
        "domains.</p>"
        '<p class="footer"><a href="/">Back</a></p>',
        theme=theme,
        field=True,
    )


#: The short phrase beside the number on a refusal, in the reader's words --
#: `CODES` in `errors.py` is the machine half and says `not_found`, which is
#: this repo's vocabulary and not a sentence anyone should be shown.
#:
#: Keyed here rather than in `errors.py` so that `portal.py` and `ops.py`, which
#: render a refusal directly and never reach that table, get the same line for
#: the same status.
STATUS_PHRASES: dict[int, str] = {
    400: "not accepted",
    401: "not signed in",
    403: "not permitted",
    404: "no such page",
    405: "no such page",
    422: "not accepted",
    429: "too many requests",
    500: "something went wrong",
    503: "records unreachable",
}


def error(
    title: str,
    message: str,
    *,
    status: int | None = None,
    heading: str | None = None,
    theme: str | None = None,
) -> str:
    """Every refusal the hub renders for a person: a wrong address, a stale
    sign-in link, a rate limit, an account that cannot sign in here.

    One function, so the graph field arrives on all of them at once and the
    next refusal someone adds gets it without being told.

    The parts a reader sees: the lockup, a numbered status line, one large
    sentence, a lede, and one way out.

    `heading` separates the sentence on the page from the words in the tab. A
    404 reads best as a sentence ("There is nothing at this address.") and a
    tab reads best as a label ("Not found").
    """
    phrase = STATUS_PHRASES.get(status or 0)
    status_line = f'<p class="status">{status} &middot; {html.escape(phrase)}</p>' if phrase else ""
    return _page(
        title,
        status_line
        + f"<h1>{html.escape(heading or title)}</h1>"
        + f'<p class="lede">{html.escape(message)}</p>'
        + '<p class="actions"><a class="button" href="/">Back to the front page</a></p>',
        theme=theme,
        field=True,
        bare=True,
    )
